// План: .qa/e2e/specs/placement-results.md, тест 2.2 (тикет #c121d3). Запасной путь: генератор не нашёл seed.
// Только просмотр: профиль постоянного тестового ребёнка QA-R2-2 у родителя. Не прогонять при записи — запуск по /qa-regress.
// Сайт оборачивает числа в невидимые метки направления (U+2066…U+2069): «משוער ⁦1 / 10⁩» — поэтому проверки регулярками с BIDI.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/parent.json') });

const BIDI = '[\\u2066-\\u2069]?';
const CHILD = 'QA-R2-2';
const CHILD_ID = '091cdbdc-551d-4f0a-b817-49f6170310af';

test.describe('Уровни в зоне родителя — готовые профили (только просмотр)', () => {
  test('Профиль неуверенно прошедшего ребёнка: неуверенность вместо одной цифры @desktop #c121d3', async ({ page }) => {
    // 1. Список детей родителя
    await page.goto('/children');

    // 2. Профиль QA-R2-2 — через «עריכת פרופיל» (карточка сама ведёт на передачу устройства /handover)
    await page.getByRole('button', { name: `עריכת פרופיל ${CHILD}` }).click();
    await page.waitForURL(new RegExp(`/children/${CHILD_ID}$`));
    await expect(page.getByRole('textbox', { name: 'שם או כינוי' })).toHaveValue(CHILD);

    // AC3: блок уровней только для родителя
    await expect(page.getByText('רמות נוכחיות (להורה בלבד)')).toBeVisible();

    const reading = page.getByText(/קריאה:/);
    const writing = page.getByText(/כתיבה:/);
    await expect(reading).toHaveCount(1);
    await expect(writing).toHaveCount(1);

    // AC4: чтение — неуверенность с оценкой, а не одна цифра
    await expect(reading).toHaveText(
      new RegExp(`^קריאה: עדיין לא ודאי · משוער ${BIDI}1 / 10${BIDI}, יתעדכן אחרי כמה תרגולים$`),
    );
    // AC4: письмо — «עדיין לא ודאי» и «1 / 4»
    await expect(writing).toContainText('עדיין לא ודאי');
    await expect(writing).toHaveText(new RegExp(`${BIDI}1 / 4${BIDI}`));

    // AC4 «ולא כרמה יחידה»: нет строки вида «קריאה: 1 / 10» / «כתיבה: 1 / 4» (голая цифра сразу после двоеточия)
    await expect(reading).not.toHaveText(new RegExp(`^קריאה: ${BIDI}\\d+ / 10`));
    await expect(writing).not.toHaveText(new RegExp(`^כתיבה: ${BIDI}\\d+ / 4`));
  });
});
